func:
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 120,
    quantity: 2
};
msg.readType = "inverterPower";
return msg;

var data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}
flow.set("inverterPowerRaw", data);

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 202,
    quantity: 1
};
msg.readType = "batteryCapacity";
return msg;

var battData = msg.payload;
if (battData && Array.isArray(battData.data)) {
    battData = battData.data;
}

var invData = flow.get("inverterPowerRaw") || [0, 0];

var ratedPowerRaw = invData[0] | (invData[1] << 16);
var ratedPowerW = ratedPowerRaw * 0.1;
var ratedPowerKw = ratedPowerW / 1000;

var batteryCapacityAh = battData[0] || 0;
var nominalVoltage = 48;
var batteryCapacityKwh = (batteryCapacityAh * nominalVoltage) / 1000;

msg.payload = {
    kind: "SystemCapacity",
    timestampUtc: new Date().toISOString(),
    inverter: {
        ratedPowerRaw: ratedPowerRaw,
        ratedPowerW: ratedPowerW,
        ratedPowerKw: ratedPowerKw
    },
    battery: {
        capacityAh: batteryCapacityAh,
        nominalVoltageV: nominalVoltage,
        capacityKwh: batteryCapacityKwh
    },
    rawRegisters: {
        reg120: invData[0],
        reg121: invData[1],
        reg202: battData[0]
    }
};

return msg;
